/**
 * CLI entry point for the YAML syntax validator.
 * Reads a YAML file by path, validates its syntax, and reports results.
 */

import { validateYaml } from "./yaml-validator";

const USAGE = `Usage: bun run validate-yaml <file>

Validates a YAML file for syntax errors.

Options:
  --help    Show this help message

Exit codes:
  0    YAML is valid
  1    YAML is invalid or an error occurred`;

const args = process.argv.slice(2);

if (args.length === 0 || args.includes("--help")) {
  console.log(USAGE);
  process.exit(args.includes("--help") ? 0 : 1);
}

const filePath = args[0];

try {
  const file = Bun.file(filePath);
  const exists = await file.exists();

  if (!exists) {
    console.error(`Error: File not found: ${filePath}`);
    process.exit(1);
  }

  const content = await file.text();
  const result = validateYaml(content);

  if (result.valid) {
    console.log(`Valid YAML: ${filePath}`);
    process.exit(0);
  } else {
    console.error(`Invalid YAML: ${filePath}`);
    for (const error of result.errors) {
      console.error(`  Line ${error.line}: ${error.message}`);
    }
    process.exit(1);
  }
} catch (err) {
  const message = err instanceof Error ? err.message : String(err);
  console.error(`Error: ${message}`);
  process.exit(1);
}

