import { describe, expect, test } from "bun:test";
import { validateYaml } from "./yaml-validator";
import type { ValidationResult, ValidationError } from "./yaml-validator";

describe("yaml-validator", () => {
  describe("result structure", () => {
    test("returns an object with valid (boolean) and errors (array)", () => {
      const result: ValidationResult = validateYaml("key: value");
      expect(typeof result.valid).toBe("boolean");
      expect(Array.isArray(result.errors)).toBe(true);
    });

    test("each error has line (number) and message (string)", () => {
      const result = validateYaml("\t bad: yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      for (const error of result.errors) {
        expect(typeof error.line).toBe("number");
        expect(typeof error.message).toBe("string");
        expect(error.line).toBeGreaterThan(0);
        expect(error.message.length).toBeGreaterThan(0);
      }
    });

    test("valid result has empty errors array", () => {
      const result = validateYaml("key: value");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });
  });

  describe("valid YAML - basic", () => {
    test("simple key-value mapping", () => {
      const yaml = "name: Alice\nage: 30";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("nested mapping", () => {
      const yaml = [
        "person:",
        "  name: Alice",
        "  address:",
        "    city: Wonderland",
        "    zip: 12345",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("sequence (list)", () => {
      const yaml = [
        "fruits:",
        "  - apple",
        "  - banana",
        "  - cherry",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("mixed mapping and sequence", () => {
      const yaml = [
        "database:",
        "  host: localhost",
        "  ports:",
        "    - 5432",
        "    - 5433",
        "  options:",
        "    timeout: 30",
        "    retries: 3",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });
  });

  describe("valid YAML - advanced", () => {
    test("literal block scalar (|)", () => {
      const yaml = [
        "description: |",
        "  This is a multi-line",
        "  string that preserves",
        "  newlines exactly.",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("folded block scalar (>)", () => {
      const yaml = [
        "summary: >",
        "  This is a folded",
        "  multi-line string",
        "  that becomes one line.",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("block scalar with chomping indicator", () => {
      const yaml = [
        "text: |-",
        "  stripped trailing newline",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("block scalar with explicit indentation indicator", () => {
      const yaml = [
        "text: |2",
        "  indented content here",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("flow sequence []", () => {
      const yaml = "colors: [red, green, blue]";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("flow mapping {}", () => {
      const yaml = "point: {x: 1, y: 2}";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("nested flow syntax", () => {
      const yaml = "data: {items: [1, 2, 3], meta: {count: 3}}";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("double-quoted strings", () => {
      const yaml = 'greeting: "Hello, World!"';
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("single-quoted strings", () => {
      const yaml = "greeting: 'Hello, World!'";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("double-quoted string with escape sequences", () => {
      const yaml = 'message: "line1\\nline2\\ttab"';
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("single-quoted string with escaped quote (doubled)", () => {
      const yaml = "message: 'it''s a test'";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("inline comments", () => {
      const yaml = [
        "name: Alice # the user's name",
        "age: 30 # in years",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("anchors and aliases", () => {
      const yaml = [
        "defaults: &defaults",
        "  timeout: 30",
        "  retries: 3",
        "production:",
        "  <<: *defaults",
        "  timeout: 60",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("multi-line flow sequence", () => {
      const yaml = [
        "items: [",
        "  one,",
        "  two,",
        "  three",
        "]",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });
  });

  describe("valid YAML - edge cases", () => {
    test("empty string", () => {
      const result = validateYaml("");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("whitespace only", () => {
      const result = validateYaml("   \n  \n    ");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("comments only", () => {
      const yaml = [
        "# This is a comment",
        "# Another comment",
        "  # Indented comment",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("document start marker (---)", () => {
      const yaml = [
        "---",
        "key: value",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("document end marker (...)", () => {
      const yaml = [
        "key: value",
        "...",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("document with both markers", () => {
      const yaml = [
        "---",
        "key: value",
        "...",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("blank lines between entries", () => {
      const yaml = [
        "key1: value1",
        "",
        "key2: value2",
        "",
        "key3: value3",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("single key-value pair", () => {
      const result = validateYaml("key: value");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });
  });

  describe("invalid YAML - tab indentation", () => {
    test("tab at start of line", () => {
      const yaml = "parent:\n\tchild: value";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);

      const tabError = result.errors.find((e) =>
        e.message.toLowerCase().includes("tab"),
      );
      expect(tabError).toBeDefined();
      expect(tabError!.line).toBe(2);
    });

    test("tab mixed with spaces", () => {
      const yaml = "parent:\n  \tchild: value";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);

      const tabError = result.errors.find((e) =>
        e.message.toLowerCase().includes("tab"),
      );
      expect(tabError).toBeDefined();
    });
  });

  describe("invalid YAML - inconsistent indentation", () => {
    test("dedent to unmatched level", () => {
      const yaml = [
        "root:",
        "    child:",
        "        grandchild: value",
        "   misaligned: value",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);

      const indentError = result.errors.find((e) =>
        e.message.toLowerCase().includes("indentation"),
      );
      expect(indentError).toBeDefined();
      expect(indentError!.line).toBe(4);
    });
  });

  describe("invalid YAML - unbalanced brackets", () => {
    test("unclosed square bracket", () => {
      const yaml = "items: [one, two, three";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);

      const bracketError = result.errors.find(
        (e) => e.message.includes("[") || e.message.includes("Unclosed"),
      );
      expect(bracketError).toBeDefined();
    });

    test("unclosed curly brace", () => {
      const yaml = "point: {x: 1, y: 2";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);

      const braceError = result.errors.find(
        (e) => e.message.includes("{") || e.message.includes("Unclosed"),
      );
      expect(braceError).toBeDefined();
    });

    test("extra closing bracket", () => {
      const yaml = "items: [one, two]]";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);

      const unexpectedError = result.errors.find((e) =>
        e.message.includes("Unexpected"),
      );
      expect(unexpectedError).toBeDefined();
    });

    test("mismatched bracket types", () => {
      const yaml = "items: [one, two}";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });
  });

  describe("invalid YAML - unbalanced quotes", () => {
    test("unterminated double-quoted string", () => {
      const yaml = 'name: "unclosed string';
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);

      const quoteError = result.errors.find((e) =>
        e.message.toLowerCase().includes("unterminated") ||
        e.message.toLowerCase().includes("double"),
      );
      expect(quoteError).toBeDefined();
    });

    test("unterminated single-quoted string", () => {
      const yaml = "name: 'unclosed string";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);

      const quoteError = result.errors.find((e) =>
        e.message.toLowerCase().includes("unterminated") ||
        e.message.toLowerCase().includes("single"),
      );
      expect(quoteError).toBeDefined();
    });
  });

  describe("invalid YAML - invalid characters", () => {
    test("control character in content", () => {
      const yaml = "key: value\x01here";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);

      const controlError = result.errors.find((e) =>
