/**
 * Core YAML syntax validator module.
 * Validates YAML content using a line-by-line state-tracking parser.
 * No external dependencies -- uses only built-in string processing.
 */

/** A single validation error with location and description. */
export interface ValidationError {
  line: number;
  message: string;
}

/** Result of a YAML validation operation. */
export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

interface LineScanResult {
  errors: ValidationError[];
  anchors: string[];
  aliases: string[];
  blockScalarDetected: boolean;
  blockScalarExplicitIndent: number;
  endsInDoubleQuote: boolean;
  endsInSingleQuote: boolean;
}

/**
 * Scan a single line character-by-character to detect quotes, brackets,
 * anchors, aliases, block scalar indicators, and syntax issues.
 */
function scanLine(
  line: string,
  lineNum: number,
  flowStack: { char: string; line: number }[],
  startInDoubleQuote: boolean,
  startInSingleQuote: boolean,
): LineScanResult {
  const errors: ValidationError[] = [];
  const anchors: string[] = [];
  const aliases: string[] = [];
  let blockScalarDetected = false;
  let blockScalarExplicitIndent = 0;
  let inDoubleQuote = startInDoubleQuote;
  let inSingleQuote = startInSingleQuote;
  let i = 0;

  while (i < line.length) {
    const ch = line[i];

    if (inDoubleQuote) {
      if (ch === "\\" && i + 1 < line.length) {
        i += 2;
        continue;
      }
      if (ch === '"') {
        inDoubleQuote = false;
      }
      i++;
      continue;
    }

    if (inSingleQuote) {
      if (ch === "'" && i + 1 < line.length && line[i + 1] === "'") {
        i += 2;
        continue;
      }
      if (ch === "'") {
        inSingleQuote = false;
        i++;
        continue;
      }
      i++;
      continue;
    }

    if (ch === "#" && (i === 0 || line[i - 1] === " " || line[i - 1] === "\t")) {
      break;
    }

    if (ch === '"') {
      inDoubleQuote = true;
      i++;
      continue;
    }

    if (ch === "'") {
      inSingleQuote = true;
      i++;
      continue;
    }

    if (ch === "[" || ch === "{") {
      flowStack.push({ char: ch, line: lineNum });
      i++;
      continue;
    }

    if (ch === "]" || ch === "}") {
      const expected = ch === "]" ? "[" : "{";
      if (flowStack.length === 0 || flowStack[flowStack.length - 1].char !== expected) {
        errors.push({
          line: lineNum,
          message: `Unexpected '${ch}' without matching opening '${expected}'`,
        });
      } else {
        flowStack.pop();
      }
      i++;
      continue;
    }

    if (
      ch === "&" &&
      (i === 0 || /[\s:\-\[\{,]/.test(line[i - 1]))
    ) {
      const match = line.slice(i).match(/^&([a-zA-Z_][a-zA-Z0-9_-]*)/);
      if (match) {
        anchors.push(match[1]);
        i += match[0].length;
        continue;
      }
    }

    if (
      ch === "*" &&
      (i === 0 || /[\s:\-\[\{,]/.test(line[i - 1]))
    ) {
      const match = line.slice(i).match(/^\*([a-zA-Z_][a-zA-Z0-9_-]*)/);
      if (match) {
        aliases.push(match[1]);
        i += match[0].length;
        continue;
      }
    }

    if ((ch === "|" || ch === ">") && flowStack.length === 0) {
      const rest = line.slice(i + 1);
      const scalarMatch = rest.match(/^([+-]?)(\d?)([+-]?)(\s*(#.*)?)$/);
      if (scalarMatch) {
        const before = line.slice(0, i).trimEnd();
        if (
          before === "" ||
          before.endsWith(":") ||
          before.endsWith("- ")  ||
          before === "-"
        ) {
          blockScalarDetected = true;
          if (scalarMatch[2]) {
            blockScalarExplicitIndent = parseInt(scalarMatch[2], 10);
          }
          break;
        }
      }
    }

    i++;
  }

  return {
    errors,
    anchors,
    aliases,
    blockScalarDetected,
    blockScalarExplicitIndent,
    endsInDoubleQuote: inDoubleQuote,
    endsInSingleQuote: inSingleQuote,
  };
}

/**
 * Check a line for invalid control characters.
 * YAML allows tab (0x09), line feed (0x0A), carriage return (0x0D),
 * and all printable Unicode. Other control characters are invalid.
 */
function checkControlCharacters(
  line: string,
  lineNum: number,
): ValidationError | null {
  for (let i = 0; i < line.length; i++) {
    const code = line.charCodeAt(i);
    if (
      (code < 0x09) ||
      (code > 0x0d && code < 0x20) ||
      code === 0x7f
    ) {
      return {
        line: lineNum,
        message: `Invalid control character at column ${i + 1} (code: 0x${code.toString(16).padStart(2, "0")})`,
      };
    }
  }
  return null;
}

/**
 * Validate YAML content for syntax correctness.
 *
 * Performs line-by-line analysis with state tracking for block scalars,
 * flow contexts, and multi-line quoted strings. Reports all detected
 * errors with line numbers and human-readable descriptions.
 */
export function validateYaml(content: string): ValidationResult {
  const errors: ValidationError[] = [];

  if (content.trim() === "") {
    return { valid: true, errors: [] };
  }

  const lines = content.split("\n");

  let inBlockScalar = false;
  let blockScalarBaseIndent = -1;
  let blockScalarExplicitIndent = -1;
  let blockScalarParentIndent = 0;
  const flowStack: { char: string; line: number }[] = [];
  let inDoubleQuote = false;
  let doubleQuoteStartLine = 0;
  let inSingleQuote = false;
  let singleQuoteStartLine = 0;
  const anchors = new Set<string>();
  const aliasRefs: { name: string; line: number }[] = [];
  const indentStack: number[] = [0];

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const rawLine = lines[i];

    const controlError = checkControlCharacters(rawLine, lineNum);
    if (controlError) {
      errors.push(controlError);
    }

    if (inDoubleQuote || inSingleQuote) {
      const scanResult = scanLine(
        rawLine,
        lineNum,
        flowStack,
        inDoubleQuote,
        inSingleQuote,
      );
      errors.push(...scanResult.errors);
      for (const a of scanResult.anchors) anchors.add(a);
      for (const a of scanResult.aliases) aliasRefs.push({ name: a, line: lineNum });
      inDoubleQuote = scanResult.endsInDoubleQuote;
      inSingleQuote = scanResult.endsInSingleQuote;
      continue;
    }

    if (inBlockScalar) {
      if (rawLine.trim() === "") {
        continue;
      }

      const currentIndent = rawLine.length - rawLine.trimStart().length;

      if (blockScalarBaseIndent === -1) {
        if (blockScalarExplicitIndent > 0) {
          blockScalarBaseIndent = blockScalarExplicitIndent;
        } else {
          blockScalarBaseIndent = currentIndent;
        }
      }

      if (currentIndent >= blockScalarBaseIndent && blockScalarBaseIndent > blockScalarParentIndent) {
        continue;
      }

      inBlockScalar = false;
      blockScalarBaseIndent = -1;
      blockScalarExplicitIndent = -1;
    }

    if (rawLine.trim() === "") {
      continue;
    }

    if (flowStack.length === 0 && !inDoubleQuote && !inSingleQuote) {
      const leadingWhitespace = rawLine.match(/^(\s*)/)?.[1] ?? "";
      if (leadingWhitespace.includes("\t")) {
        errors.push({
          line: lineNum,
          message: "Tab character used for indentation; YAML requires spaces only",
        });
        continue;
      }
    }

    const trimmed = rawLine.trim();

    if (trimmed.startsWith("#")) {
      continue;
    }

    if (rawLine === "---" || rawLine === "...") {
      indentStack.length = 0;
      indentStack.push(0);
      continue;
    }

    const indent = rawLine.length - rawLine.trimStart().length;

    if (flowStack.length === 0) {
      if (indent > indentStack[indentStack.length - 1]) {
        indentStack.push(indent);
      } else if (indent < indentStack[indentStack.length - 1]) {
        let found = false;
        for (let j = indentStack.length - 1; j >= 0; j--) {
          if (indentStack[j] === indent) {
            indentStack.length = j + 1;
            found = true;
            break;
          }
        }
        if (!found) {
          errors.push({
            line: lineNum,
            message: `Inconsistent indentation: ${indent} spaces does not match any previous indentation level`,
          });
        }
      }
    }

    const scanResult = scanLine(
      rawLine,
      lineNum,
      flowStack,
      false,
      false,
    );

    errors.push(...scanResult.errors);

    for (const a of scanResult.anchors) anchors.add(a);
    for (const a of scanResult.aliases) aliasRefs.push({ name: a, line: lineNum });

    if (scanResult.endsInDoubleQuote) {
      inDoubleQuote = true;
      doubleQuoteStartLine = lineNum;
    }
    if (scanResult.endsInSingleQuote) {
      inSingleQuote = true;
      singleQuoteStartLine = lineNum;
    }

    if (scanResult.blockScalarDetected && flowStack.length === 0) {
      inBlockScalar = true;
      blockScalarBaseIndent = -1;
      blockScalarParentIndent = indent;
      if (scanResult.blockScalarExplicitIndent > 0) {
        blockScalarExplicitIndent = indent + scanResult.blockScalarExplicitIndent;
      } else {
        blockScalarExplicitIndent = -1;
      }
    }
  }

  if (flowStack.length > 0) {
    const unclosed = flowStack[flowStack.length - 1];
    const expected = unclosed.char === "[" ? "]" : "}";
    errors.push({
      line: unclosed.line,
      message: `Unclosed '${unclosed.char}', expected matching '${expected}'`,
    });
  }

  if (inDoubleQuote) {
    errors.push({
      line: doubleQuoteStartLine,
      message: "Unterminated double-quoted string",
    });
  }

  if (inSingleQuote) {
    errors.push({
      line: singleQuoteStartLine,
      message: "Unterminated single-quoted string",
    });
  }

  for (const alias of aliasRefs) {
    if (!anchors.has(alias.name)) {
      errors.push({
        line: alias.line,
        message: `Alias '*${alias.name}' references undefined anchor '&${alias.name}'`,
      });
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

