   318→            line: lineNum,
   319→            message: `Inconsistent indentation: ${indent} spaces does not match any previous indentation level`,
   320→          });
   321→        }
   322→      }
   323→    }
   324→
   325→    const scanResult = scanLine(
   326→      rawLine,
   327→      lineNum,
   328→      flowStack,
   329→      false,
   330→      false,
   331→    );
   332→
   333→    errors.push(...scanResult.errors);
   334→
   335→    for (const a of scanResult.anchors) anchors.add(a);
   336→    for (const a of scanResult.aliases) aliasRefs.push({ name: a, line: lineNum });
