     1→/**
     2→ * Core YAML syntax validator module.
     3→ * Validates YAML content using a line-by-line state-tracking parser.
     4→ * No external dependencies -- uses only built-in string processing.
     5→ */
     6→
     7→/** A single validation error with location and description. */
     8→export interface ValidationError {
     9→  line: number;
    10→  message: string;
    11→}
    12→
    13→/** Result of a YAML validation operation. */
    14→export interface ValidationResult {
    15→  valid: boolean;
    16→  errors: ValidationError[];
    17→}
    18→
    19→interface LineScanResult {
    20→  errors: ValidationError[];
    21→  anchors: string[];
    22→  aliases: string[];
    23→  blockScalarDetected: boolean;
    24→  blockScalarExplicitIndent: number;
    25→  endsInDoubleQuote: boolean;
    26→  endsInSingleQuote: boolean;
    27→}
    28→
    29→/**
    30→ * Scan a single line character-by-character to detect quotes, brackets,
    31→ * anchors, aliases, block scalar indicators, and syntax issues.
    32→ */
    33→function scanLine(
    34→  line: string,
    35→  lineNum: number,
    36→  flowStack: { char: string; line: number }[],
    37→  startInDoubleQuote: boolean,
    38→  startInSingleQuote: boolean,
    39→): LineScanResult {
    40→  const errors: ValidationError[] = [];
    41→  const anchors: string[] = [];
    42→  const aliases: string[] = [];
    43→  let blockScalarDetected = false;
    44→  let blockScalarExplicitIndent = 0;
    45→  let inDoubleQuote = startInDoubleQuote;
    46→  let inSingleQuote = startInSingleQuote;
    47→  let i = 0;
    48→
    49→  while (i < line.length) {
    50→    const ch = line[i];
    51→
    52→    if (inDoubleQuote) {
    53→      if (ch === "\\" && i + 1 < line.length) {
    54→        i += 2;
    55→        continue;
    56→      }
    57→      if (ch === '"') {
    58→        inDoubleQuote = false;
    59→      }
    60→      i++;
    61→      continue;
    62→    }
    63→
    64→    if (inSingleQuote) {
    65→      if (ch === "'" && i + 1 < line.length && line[i + 1] === "'") {
    66→        i += 2;
    67→        continue;
    68→      }
    69→      if (ch === "'") {
    70→        inSingleQuote = false;
    71→        i++;
    72→        continue;
    73→      }
    74→      i++;
    75→      continue;
    76→    }
    77→
    78→    if (ch === "#" && (i === 0 || line[i - 1] === " " || line[i - 1] === "\t")) {
    79→      break;
    80→    }
    81→
    82→    if (ch === '"') {
    83→      inDoubleQuote = true;
    84→      i++;
    85→      continue;
    86→    }
    87→
    88→    if (ch === "'") {
    89→      inSingleQuote = true;
    90→      i++;
    91→      continue;
    92→    }
    93→
    94→    if (ch === "[" || ch === "{") {
    95→      flowStack.push({ char: ch, line: lineNum });
    96→      i++;
    97→      continue;
    98→    }
    99→
   100→    if (ch === "]" || ch === "}") {
   101→      const expected = ch === "]" ? "[" : "{";
   102→      if (flowStack.length === 0 || flowStack[flowStack.length - 1].char !== expected) {
   103→        errors.push({
   104→          line: lineNum,
   105→          message: `Unexpected '${ch}' without matching opening '${expected}'`,
   106→        });
   107→      } else {
   108→        flowStack.pop();
   109→      }
   110→      i++;
   111→      continue;
   112→    }
   113→
   114→    if (
   115→      ch === "&" &&
   116→      (i === 0 || /[\s:\-\[\{,]/.test(line[i - 1]))
   117→    ) {
   118→      const match = line.slice(i).match(/^&([a-zA-Z_][a-zA-Z0-9_-]*)/);
   119→      if (match) {
   120→        anchors.push(match[1]);
   121→        i += match[0].length;
   122→        continue;
   123→      }
   124→    }
   125→
   126→    if (
   127→      ch === "*" &&
   128→      (i === 0 || /[\s:\-\[\{,]/.test(line[i - 1]))
   129→    ) {
   130→      const match = line.slice(i).match(/^\*([a-zA-Z_][a-zA-Z0-9_-]*)/);
   131→      if (match) {
   132→        aliases.push(match[1]);
   133→        i += match[0].length;
   134→        continue;
   135→      }
   136→    }
   137→
   138→    if ((ch === "|" || ch === ">") && flowStack.length === 0) {
   139→      const rest = line.slice(i + 1);
   140→      const scalarMatch = rest.match(/^([+-]?)(\d?)([+-]?)(\s*(#.*)?)$/);
   141→      if (scalarMatch) {
   142→        const before = line.slice(0, i).trimEnd();
   143→        if (
   144→          before === "" ||
   145→          before.endsWith(":") ||
   146→          before.endsWith("- ")  ||
   147→          before === "-"
   148→        ) {
   149→          blockScalarDetected = true;
   150→          if (scalarMatch[2]) {
   151→            blockScalarExplicitIndent = parseInt(scalarMatch[2], 10);
   152→          }
   153→          break;
   154→        }
   155→      }
   156→    }
   157→
   158→    i++;
   159→  }
   160→
   161→  return {
   162→    errors,
   163→    anchors,
   164→    aliases,
   165→    blockScalarDetected,
   166→    blockScalarExplicitIndent,
   167→    endsInDoubleQuote: inDoubleQuote,
   168→    endsInSingleQuote: inSingleQuote,
   169→  };
   170→}
