   172→/**
   173→ * Check a line for invalid control characters.
   174→ * YAML allows tab (0x09), line feed (0x0A), carriage return (0x0D),
   175→ * and all printable Unicode. Other control characters are invalid.
   176→ */
   177→function checkControlCharacters(
   178→  line: string,
   179→  lineNum: number,
   180→): ValidationError | null {
   181→  for (let i = 0; i < line.length; i++) {
   182→    const code = line.charCodeAt(i);
   183→    if (
   184→      (code < 0x09) ||
   185→      (code > 0x0d && code < 0x20) ||
   186→      code === 0x7f
   187→    ) {
   188→      return {
   189→        line: lineNum,
   190→        message: `Invalid control character at column ${i + 1} (code: 0x${code.toString(16).padStart(2, "0")})`,
   191→      };
   192→    }
   193→  }
   194→  return null;
   195→}
   196→
   197→/**
   198→ * Validate YAML content for syntax correctness.
   199→ *
   200→ * Performs line-by-line analysis with state tracking for block scalars,
   201→ * flow contexts, and multi-line quoted strings. Reports all detected
   202→ * errors with line numbers and human-readable descriptions.
   203→ */
   204→export function validateYaml(content: string): ValidationResult {
   205→  const errors: ValidationError[] = [];
   206→
   207→  if (content.trim() === "") {
   208→    return { valid: true, errors: [] };
   209→  }
   210→
   211→  const lines = content.split("\n");
   212→
   213→  let inBlockScalar = false;
   214→  let blockScalarBaseIndent = -1;
   215→  let blockScalarExplicitIndent = -1;
   216→  let blockScalarParentIndent = 0;
   217→  const flowStack: { char: string; line: number }[] = [];
   218→  let inDoubleQuote = false;
   219→  let doubleQuoteStartLine = 0;
   220→  let inSingleQuote = false;
   221→  let singleQuoteStartLine = 0;
   222→  const anchors = new Set<string>();
   223→  const aliasRefs: { name: string; line: number }[] = [];
   224→  const indentStack: number[] = [0];
   225→
   226→  for (let i = 0; i < lines.length; i++) {
   227→    const lineNum = i + 1;
   228→    const rawLine = lines[i];
   229→
   230→    const controlError = checkControlCharacters(rawLine, lineNum);
   231→    if (controlError) {
   232→      errors.push(controlError);
   233→    }
   234→
   235→    if (inDoubleQuote || inSingleQuote) {
   236→      const scanResult = scanLine(
   237→        rawLine,
   238→        lineNum,
   239→        flowStack,
   240→        inDoubleQuote,
   241→        inSingleQuote,
   242→      );
   243→      errors.push(...scanResult.errors);
   244→      for (const a of scanResult.anchors) anchors.add(a);
   245→      for (const a of scanResult.aliases) aliasRefs.push({ name: a, line: lineNum });
   246→      inDoubleQuote = scanResult.endsInDoubleQuote;
   247→      inSingleQuote = scanResult.endsInSingleQuote;
   248→      continue;
   249→    }
   250→
   251→    if (inBlockScalar) {
   252→      if (rawLine.trim() === "") {
   253→        continue;
   254→      }
   255→
   256→      const currentIndent = rawLine.length - rawLine.trimStart().length;
   257→
   258→      if (blockScalarBaseIndent === -1) {
   259→        if (blockScalarExplicitIndent > 0) {
   260→          blockScalarBaseIndent = blockScalarExplicitIndent;
   261→        } else {
   262→          blockScalarBaseIndent = currentIndent;
   263→        }
   264→      }
   265→
   266→      if (currentIndent >= blockScalarBaseIndent && blockScalarBaseIndent > blockScalarParentIndent) {
   267→        continue;
   268→      }
   269→
   270→      inBlockScalar = false;
   271→      blockScalarBaseIndent = -1;
   272→      blockScalarExplicitIndent = -1;
   273→    }
   274→
   275→    if (rawLine.trim() === "") {
   276→      continue;
   277→    }
   278→
   279→    if (flowStack.length === 0 && !inDoubleQuote && !inSingleQuote) {
   280→      const leadingWhitespace = rawLine.match(/^(\s*)/)?.[1] ?? "";
   281→      if (leadingWhitespace.includes("\t")) {
   282→        errors.push({
   283→          line: lineNum,
   284→          message: "Tab character used for indentation; YAML requires spaces only",
   285→        });
   286→        continue;
   287→      }
   288→    }
   289→
   290→    const trimmed = rawLine.trim();
   291→
   292→    if (trimmed.startsWith("#")) {
   293→      continue;
   294→    }
   295→
   296→    if (rawLine === "---" || rawLine === "...") {
   297→      indentStack.length = 0;
   298→      indentStack.push(0);
   299→      continue;
   300→    }
   301→
   302→    const indent = rawLine.length - rawLine.trimStart().length;
   303→
   304→    if (flowStack.length === 0) {
   305→      if (indent > indentStack[indentStack.length - 1]) {
   306→        indentStack.push(indent);
   307→      } else if (indent < indentStack[indentStack.length - 1]) {
   308→        let found = false;
   309→        for (let j = indentStack.length - 1; j >= 0; j--) {
   310→          if (indentStack[j] === indent) {
   311→            indentStack.length = j + 1;
   312→            found = true;
   313→            break;
   314→          }
   315→        }
   316→        if (!found) {
   317→          errors.push({
   318→            line: lineNum,
   319→            message: `Inconsistent indentation: ${indent} spaces does not match any previous indentation level`,
   320→          });
   321→        }
   322→      }
   323→    }
   324→
   325→    const scanResult = scanLine(
   326→      rawLine,
   327→      lineNum,
   328→      flowStack,
   329→      false,
   330→      false,
   331→    );
   332→
   333→    errors.push(...scanResult.errors);
   334→
   335→    for (const a of scanResult.anchors) anchors.add(a);
   336→    for (const a of scanResult.aliases) aliasRefs.push({ name: a, line: lineNum });
   337→
   338→    if (scanResult.endsInDoubleQuote) {
   339→      inDoubleQuote = true;
   340→      doubleQuoteStartLine = lineNum;
   341→    }
   342→    if (scanResult.endsInSingleQuote) {
   343→      inSingleQuote = true;
   344→      singleQuoteStartLine = lineNum;
   345→    }
   346→
   347→    if (scanResult.blockScalarDetected && flowStack.length === 0) {
   348→      inBlockScalar = true;
   349→      blockScalarBaseIndent = -1;
   350→      blockScalarParentIndent = indent;
   351→      if (scanResult.blockScalarExplicitIndent > 0) {
   352→        blockScalarExplicitIndent = indent + scanResult.blockScalarExplicitIndent;
   353→      } else {
   354→        blockScalarExplicitIndent = -1;
   355→      }
   356→    }
   357→  }
   358→
   359→  if (flowStack.length > 0) {
   360→    const unclosed = flowStack[flowStack.length - 1];
   361→    const expected = unclosed.char === "[" ? "]" : "}";
   362→    errors.push({
   363→      line: unclosed.line,
   364→      message: `Unclosed '${unclosed.char}', expected matching '${expected}'`,
   365→    });
   366→  }
   367→
   368→  if (inDoubleQuote) {
   369→    errors.push({
   370→      line: doubleQuoteStartLine,
   371→      message: "Unterminated double-quoted string",
   372→    });
   373→  }
   374→
   375→  if (inSingleQuote) {
   376→    errors.push({
   377→      line: singleQuoteStartLine,
   378→      message: "Unterminated single-quoted string",
   379→    });
   380→  }
   381→
   382→  for (const alias of aliasRefs) {
   383→    if (!anchors.has(alias.name)) {
   384→      errors.push({
   385→        line: alias.line,
   386→        message: `Alias '*${alias.name}' references undefined anchor '&${alias.name}'`,
   387→      });
   388→    }
   389→  }
   390→
   391→  return {
   392→    valid: errors.length === 0,
   393→    errors,
   394→  };
   395→}
