     1→/**
     2→ * CLI entry point for the YAML syntax validator.
     3→ * Reads a YAML file by path, validates its syntax, and reports results.
     4→ */
     5→
     6→import { validateYaml } from "./yaml-validator";
     7→
     8→const USAGE = `Usage: bun run validate-yaml <file>
     9→
    10→Validates a YAML file for syntax errors.
    11→
    12→Options:
    13→  --help    Show this help message
    14→
    15→Exit codes:
    16→  0    YAML is valid
    17→  1    YAML is invalid or an error occurred`;
    18→
    19→const args = process.argv.slice(2);
    20→
    21→if (args.length === 0 || args.includes("--help")) {
    22→  console.log(USAGE);
    23→  process.exit(args.includes("--help") ? 0 : 1);
    24→}
    25→
    26→const filePath = args[0];
    27→
    28→try {
    29→  const file = Bun.file(filePath);
    30→  const exists = await file.exists();
    31→
    32→  if (!exists) {
    33→    console.error(`Error: File not found: ${filePath}`);
    34→    process.exit(1);
    35→  }
    36→
    37→  const content = await file.text();
    38→  const result = validateYaml(content);
    39→
    40→  if (result.valid) {
    41→    console.log(`Valid YAML: ${filePath}`);
    42→    process.exit(0);
    43→  } else {
    44→    console.error(`Invalid YAML: ${filePath}`);
    45→    for (const error of result.errors) {
    46→      console.error(`  Line ${error.line}: ${error.message}`);
    47→    }
    48→    process.exit(1);
    49→  }
    50→} catch (err) {
    51→  const message = err instanceof Error ? err.message : String(err);
    52→  console.error(`Error: ${message}`);
    53→  process.exit(1);
    54→}
